def equationsPossible(n, equations):
    parent = list(range(n))

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    for a, op, b in equations:
        if op == 0:
            ra, rb = find(a), find(b)
            if ra != rb:
                parent[ra] = rb
    for a, op, b in equations:
        if op == 1 and find(a) == find(b):
            return False
    return True
